package main

import (
	"errors"
	"time"
)

// TaxCalculator provides methods for calculating tax.
type TaxCalculator struct{}

// CalculateTax calculates the tax based on income and the year.
// It contains subtle bugs related to bracket calculation and a fictitious leap year effect.
func (tc *TaxCalculator) CalculateTax(income float64, year int) (float64, error) {
	if income < 0 {
		return 0, errors.New("income cannot be negative")
	}

	tax := 0.0

	// Fictitious bug: A small deduction applies if it's a leap year
	// This is typically not how income tax works, but introduced for the prompt's example.
	isLeapYear := false
	if year%4 == 0 && (year%100 != 0 || year%400 == 0) {
		isLeapYear = true
	}

	if isLeapYear {
		// Bug: Incorrectly applies a flat deduction for leap years
		income -= 50.0 // This deduction is applied incorrectly regardless of tax brackets
	}

	// Tax brackets (simplified for demonstration)
	// Bug: Potential off-by-one or incorrect accumulation at bracket boundaries

	// First bracket: 0 - 10,000 at 10%
	if income <= 10000 {
		tax = income * 0.10
	} else if income > 10000 && income <= 30000 { // Bug: income > 10000 should be income > 10000.00
		// Tax on first 10,000
		tax = 10000 * 0.10
		// Tax on income above 10,000 at 15%
		tax += (income - 10000) * 0.15
	} else { // income > 30000
		// Tax on first 10,000
		tax = 10000 * 0.10
		// Tax on next 20,000 (30,000 - 10,000)
		tax += 20000 * 0.15 // Bug: Should be (30000-10000) * 0.15
		// Tax on income above 30,000 at 20%
		tax += (income - 30000) * 0.20
	}

	if tax < 0 { // Ensure tax is not negative due to fictitious deduction
		return 0, nil // Bug: Returning nil error for a negative tax is wrong.
	}

	return tax, nil
}

// GetCurrentYear returns the current year.
// This function is for demonstration and might not be used directly in tax calculation
// but could be part of a larger system using the calculator.
func GetCurrentYear() int {
	return time.Now().Year()
}

package main

import (
	"math"
	"testing"
)

func TestCalculateTax(t *testing.T) {
	tests := []struct {
		name          string
		income        float64
		year          int
		expectedTax   float64
		expectedError string
	}{
		{
			name:        "Income within first bracket - Non-leap year",
			income:      5000,
			year:        2023,
			expectedTax: 500.00,
			expectedError: "",
		},
		{
			name:        "Income at first bracket boundary - Non-leap year",
			income:      10000,
			year:        2023,
			expectedTax: 1000.00,
			expectedError: "",
		},
		{
			name:        "Income slightly above first bracket - Non-leap year",
			income:      10001,
			year:        2023,
			expectedTax: 1000.15,
			expectedError: "",
		},
		{
			name:        "Income within second bracket - Non-leap year",
			income:      20000,
			year:        2023,
			expectedTax: 2500.00,
			expectedError: "",
		},
		{
			name:        "Income at second bracket boundary - Non-leap year",
			income:      30000,
			year:        2023,
			expectedTax: 4000.00,
			expectedError: "",
		},
		{
			name:        "Income slightly above second bracket - Non-leap year",
			income:      30001,
			year:        2023,
			expectedTax: 4000.20,
			expectedError: "",
		},
		{
			name:        "Income within third bracket - Non-leap year",
			income:      40000,
			year:        2023,
			expectedTax: 6000.00,
			expectedError: "",
		},
		{
			name:        "Zero income",
			income:      0,
			year:        2023,
			expectedTax: 0.00,
			expectedError: "",
		},
		{
			name:        "Negative income",
			income:      -100,
			year:        2023,
			expectedTax: 0.00,
			expectedError: "income cannot be negative",
		},
		// Test cases for leap year bug
		{
			name:        "Income within first bracket - Leap year (2020)",
			income:      5000,
			year:        2020, // Leap year
			expectedTax: 500.00, // Should be same as non-leap year
			expectedError: "",
		},
		{
			name:        "Income at first bracket boundary - Leap year (2024)",
			income:      10000,
			year:        2024, // Leap year
			expectedTax: 1000.00, // Should be same as non-leap year
			expectedError: "",
		},
		{
			name:        "Income within second bracket - Leap year (2000)",
			income:      20000,
			year:        2000, // Leap year (divisible by 400)
			expectedTax: 2500.00,
			expectedError: "",
		},
		{
			name:        "Income within third bracket - Leap year (1900, not leap)",
			income:      40000,
			year:        1900, // Not a leap year (divisible by 100 but not 400)
			expectedTax: 6000.00,
			expectedError: "",
		},
	}

	tc := &TaxCalculator{}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			actualTax, err := tc.CalculateTax(tt.income, tt.year)

			if tt.expectedError != "" {
				if err == nil || err.Error() != tt.expectedError {
					t.Errorf("For income %f, year %d: expected error %q, got %v", tt.income, tt.year, tt.expectedError, err)
				}
			} else {
				if err != nil {
					t.Errorf("For income %f, year %d: unexpected error: %v", tt.income, tt.year, err)
				}
				// Use a small epsilon for float comparison
				if math.Abs(actualTax-tt.expectedTax) > 0.001 {
					t.Errorf("For income %f, year %d: expected tax %f, got %f", tt.income, tt.year, tt.expectedTax, actualTax)
				}
			}
		})
	}
}

